static const char __pyx_k_Hermes_CLI_skin_theme_engine_A_d[] = "Hermes CLI skin/theme engine.\n\nA data-driven skin system that lets users customize the CLI's visual appearance.\nSkins are defined as YAML files in ~/.hermes/skins/ or as built-in presets.\nNo code changes are needed to add a new skin.\n\nSKIN YAML SCHEMA\n================\n\nAll fields are optional. Missing values inherit from the ``default`` skin.\n\n.. code-block:: yaml\n\n    # Required: skin identity\n    name: mytheme                         # Unique skin name (lowercase, hyphens ok)\n    description: Short description        # Shown in /skin listing\n\n    # Colors: hex values for Rich markup (banner, UI, response box)\n    colors:\n      banner_border: \"#CD7F32\"            # Panel border color\n      banner_title: \"#FFD700\"             # Panel title text color\n      banner_accent: \"#FFBF00\"            # Section headers (Available Tools, etc.)\n      banner_dim: \"#B8860B\"               # Dim/muted text (separators, labels)\n      banner_text: \"#FFF8DC\"              # Body text (tool names, skill names)\n      ui_accent: \"#FFBF00\"               # General UI accent\n      ui_label: \"#4dd0e1\"                # UI labels\n      ui_ok: \"#4caf50\"                   # Success indicators\n      ui_error: \"#ef5350\"                # Error indicators\n      ui_warn: \"#ffa726\"                 # Warning indicators\n      prompt: \"#FFF8DC\"                  # Prompt text color\n      input_rule: \"#CD7F32\"              # Input area horizontal rule\n      response_border: \"#FFD700\"         # Response box border (ANSI)\n      session_label: \"#DAA520\"           # Session label color\n      session_border: \"#8B8682\"          # Session ID dim color\n\n    # Spinner: customize the animated spinner during API calls\n    spinner:\n      waiting_faces:                      # Faces shown while waiting for API\n        - \"(\342\232\224)\"\n        - \"(\342\233\250)\"\n      thinking_faces:                     # Faces shown during reasoning\n        - ""\"(\342\214\201)\"\n        - \"(<>)\"\n      thinking_verbs:                     # Verbs for spinner messages\n        - \"forging\"\n        - \"plotting\"\n      wings:                              # Optional left/right spinner decorations\n        - [\"\342\237\252\342\232\224\", \"\342\232\224\342\237\253\"]                  # Each entry is [left, right] pair\n        - [\"\342\237\252\342\226\262\", \"\342\226\262\342\237\253\"]\n\n    # Branding: text strings used throughout the CLI\n    branding:\n      agent_name: \"Hermes Agent\"          # Banner title, status display\n      welcome: \"Welcome message\"          # Shown at CLI startup\n      goodbye: \"Goodbye! \342\232\225\"              # Shown on exit\n      response_label: \" \342\232\225 Hermes \"       # Response box header label\n      prompt_symbol: \"\342\235\257 \"                # Input prompt symbol\n      help_header: \"(^_^)? Commands\"      # /help header text\n\n    # Tool prefix: character for tool output lines (default: \342\224\212)\n    tool_prefix: \"\342\224\212\"\n\n    # Tool emojis: override the default emoji for any tool (used in spinners & progress)\n    tool_emojis:\n      terminal: \"\342\232\224\"           # Override terminal tool emoji\n      web_search: \"\360\237\224\256\"        # Override web_search tool emoji\n      # Any tool not listed here uses its registry default\n\nUSAGE\n=====\n\n.. code-block:: python\n\n    from hermes_cli.skin_engine import get_active_skin, list_skins, set_active_skin\n\n    skin = get_active_skin()\n    print(skin.colors[\"banner_title\"])    # \"#FFD700\"\n    print(skin.get_branding(\"agent_name\"))  # \"Hermes Agent\"\n\n    set_active_skin(\"ares\")               # Switch to built-in ares skin\n    set_active_skin(\"mytheme\")            # Switch to user skin from ~/.hermes/skins/\n\nBUILT-IN SKINS\n==============\n\n- ``default`` \342\200\224 Classic Hermes gold/kawaii (the current look)\n- ``ares``    \342\200\224 Crimson/bronze war-go""d theme with custom spinner wings\n- ``mono``    \342\200\224 Clean grayscale monochrome\n- ``slate``   \342\200\224 Cool blue developer-focused theme\n\nUSER SKINS\n==========\n\nDrop a YAML file in ``~/.hermes/skins/<name>.yaml`` following the schema above.\nActivate with ``/skin <name>`` in the CLI or ``display.skin: <name>`` in config.yaml.\n";
